export function colIndexToLetters(idx) {
  let res = "";
  let n = idx + 1;
  while (n > 0) {
    const rem = (n - 1) % 26;
    res = String.fromCharCode(65 + rem) + res;
    n = Math.floor((n - 1) / 26);
  }
  return res;
}

export function lettersToColIndex(letters) {
  let num = 0;
  for (let i = 0; i < letters.length; i++) {
    num = num * 26 + (letters.charCodeAt(i) - 64);
  }
  return num - 1;
}

export function getSheetIndex(sheetName) {
  return WORKBOOK_DATA.findIndex(
    (s) => s.name.toLowerCase() === String(sheetName || "").toLowerCase()
  );
}

export function parseRange(rangeStr) {
  if (!rangeStr) return null;
  const clean = String(rangeStr).trim().toUpperCase();
  const [startRef, endRef = startRef] = clean.split(":");
  const m1 = /^([A-Z]+)(\d+)$/.exec(startRef);
  const m2 = /^([A-Z]+)(\d+)$/.exec(endRef);
  if (!m1 || !m2) return null;
  const c1 = lettersToColIndex(m1[1]);
  const r1 = Number(m1[2]);
  const c2 = lettersToColIndex(m2[1]);
  const r2 = Number(m2[2]);
  return {
    startRow: Math.min(r1, r2),
    endRow: Math.max(r1, r2),
    startCol: Math.min(c1, c2),
    endCol: Math.max(c1, c2),
  };
}
